class Solution {
public:
    bool repeatedSubstringPattern(string s) {
        int n = s.size();
        vector<int> lps(n, 0);
        int prev = 0, i = 1;
        while (i < n) {
            if (s[i] == s[prev]) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int period = n - lps.back();
        return lps.back() > 0 && (n % period == 0);
    }
};

class Solution {
    public boolean repeatedSubstringPattern(String s) {
        int n = s.length();
        int[] lps = new int[n];
        int prev = 0, i = 1;
        while (i < n) {
            if (s.charAt(i) == s.charAt(prev)) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        int period = n - lps[n - 1];
        return lps[n - 1] > 0 && (n % period == 0);
    }
}

var repeatedSubstringPattern = function(s) {
